{% assign trustpilot_locale = 'fr-FR' %}
{% if request.locale.iso_code contains 'en' %}{% assign trustpilot_locale = 'en-GB' %}{% endif %}
<bestini-cart-trustpilot-compact style="display:block;margin:8px auto 0;width:100%;max-width:100%;overflow:visible;">
<div class="trustpilot-widget" data-locale="{{ trustpilot_locale }}" data-template-id="54ad5defc6454f065c28af8b" data-businessunit-id="662238c924be3c7f07c46e85" data-style-height="240px" data-style-width="100%" data-token="5c9a050c-c3ed-4557-b86d-b590cbdf3d59" data-stars="4,5" data-font-family="Montserrat">
  <a href="https://fr.trustpilot.com/review/bestiniparis.com" target="_blank" rel="noopener">Trustpilot</a>
</div>
</bestini-cart-trustpilot-compact>
<script>
(function loadTrustpilotBootstrap() {
  if (window.Trustpilot || document.getElementById('bestini-tp-bootstrap')) return;
  var s = document.createElement('script');
  s.id = 'bestini-tp-bootstrap';
  s.src = '//widget.trustpilot.com/bootstrap/v5/tp.widget.bootstrap.min.js';
  s.async = true;
  document.head.appendChild(s);
})();

if (!customElements.get('bestini-cart-trustpilot-compact')) {
  customElements.define('bestini-cart-trustpilot-compact', class extends HTMLElement {
    connectedCallback() {
      let attempts = 0;
      const initialize = () => {
        if (!this.isConnected) return;
        const block = this.closest('.cart-block');
        const foot = block && block.parentElement;
        if (foot && foot.classList.contains('drawer__foot') && foot.lastElementChild !== block) {
          foot.appendChild(block);
          return;
        }
        const widget = this.querySelector('.trustpilot-widget');
        if (widget && window.Trustpilot && window.Trustpilot.loadFromElement) {
          window.Trustpilot.loadFromElement(widget, true);
        } else if (++attempts < 80) {
          this.timer = setTimeout(initialize, 250);
        }
      };
      this.timer = setTimeout(initialize, 0);
    }
    disconnectedCallback() { clearTimeout(this.timer); }
  });
}
</script>
<style>
.drawer__foot > .cart-block:has(bestini-cart-trustpilot-compact) { padding-top: 0; }
.drawer__foot > .cart-block:has(bestini-cart-trustpilot-compact) .cart__custom-code { padding-top: 0; }
.drawer__foot > .cart-block:has(+ .cart-block bestini-cart-trustpilot-compact),
.drawer__foot > .cart-block:has(+ .cart-block bestini-cart-trustpilot-compact) .cart__foot__inner { padding-bottom: 0; }
</style>
